		this.#globalListenersRegistered = false;
	}

	/**
	 * Calculates the intersection between a target and the root.
	 *
	 * @param target Target.
	 * @returns Calculation.
	 */
	private #calculateIntersection(
		target: Element
	): IIntersectionObserverCalculation {
		const window = this[PropertySymbol.window];

		const targetBox = this.#getBox(target.getBoundingClientRect());
		const rootBox = this.#getRootBox();

		const targetWidth = targetBox.right - targetBox.left;
		const targetHeight = targetBox.bottom - targetBox.top;
		const targetArea = targetWidth * targetHeight;

		let intersectionRatio: number;
		let intersectionBox: IIntersectionObserverBox;

		if (targetArea === 0) {
			// Zero area targets have a ratio of 1 if they are contained by the root, otherwise 0.
			const isContained =
				targetBox.left >= rootBox.left &&
				targetBox.right <= rootBox.right &&
				targetBox.top >= rootBox.top &&
				targetBox.bottom <= rootBox.bottom;

			if (isContained) {
				intersectionRatio = 1;
				intersectionBox = targetBox;
			} else {
				intersectionRatio = 0;
				intersectionBox = { left: 0, top: 0, right: 0, bottom: 0 };
			}
		} else {
			const left = Math.max(targetBox.left, rootBox.left);
			const top = Math.max(targetBox.top, rootBox.top);
			const right = Math.min(targetBox.right, rootBox.right);
			const bottom = Math.min(targetBox.bottom, rootBox.bottom);
			const width = Math.max(0, right - left);
			const height = Math.max(0, bottom - top);

			intersectionRatio = Math.min(1, Math.max(0, (width * height) / targetArea));
			intersectionBox =
				width > 0 && height > 0
					? { left, top, right: left + width, bottom: top + height }
					: { left: 0, top: 0, right: 0, bottom: 0 };
		}

		return {
			intersectionRatio,
			boundingClientRect: new window.DOMRect(
				targetBox.left,
				targetBox.top,
				targetBox.right - targetBox.left,
				targetBox.bottom - targetBox.top
			),
			intersectionRect: new window.DOMRect(
				intersectionBox.left,
				intersectionBox.top,
				intersectionBox.right - intersectionBox.left,
				intersectionBox.bottom - intersectionBox.top
			),
			rootBounds: new window.DOMRect(
				rootBox.left,
				rootBox.top,
				rootBox.right - rootBox.left,
				rootBox.bottom - rootBox.top
			)
		};
	}

	/**
	 * Determines if an entry should be queued for a target.
	 *
	 * @param state Target state.
	 * @param intersectionRatio New intersection ratio.
	 * @returns True if an entry should be queued.
	 */
	private #shouldQueueEntry(
		state: IIntersectionObserverTargetState,
		intersectionRatio: number
	): boolean {
		const previousRatio = state.intersectionRatio;

		if (previousRatio === null) {
			return true;
		}

		if (previousRatio === intersectionRatio) {
			return false;
		}

		// An entry is always queued when the target starts or stops intersecting.
		if ((previousRatio > 0) !== (intersectionRatio > 0)) {
			return true;
		}

		// An entry is queued when the intersection ratio crosses any of the thresholds.
		return this.#thresholds.some(
			(threshold) =>
				(previousRatio < threshold && intersectionRatio >= threshold) ||
				(intersectionRatio < threshold && previousRatio >= threshold)
		);
	}

	/**
	 * Creates an entry for a target.
	 *
	 * @param target Target.
	 * @param calculation Calculation.
	 * @returns Entry.
	 */
	private #createEntry(
		target: Element,
		calculation: IIntersectionObserverCalculation
	): IntersectionObserverEntry {
		return new (this[PropertySymbol.window].IntersectionObserverEntry)({
			time: Date.now(),
			target,
			rootBounds: calculation.rootBounds,
			boundingClientRect: calculation.boundingClientRect,
			intersectionRect: calculation.intersectionRect,
			intersectionRatio: calculation.intersectionRatio,
			isIntersecting: calculation.intersectionRatio > 0
		});
	}

	/**
	 * Gets the box of the root including any root margin.
	 *
	 * @returns Box.
	 */
	private #getRootBox(): IIntersectionObserverBox {
		const window = this[PropertySymbol.window];

		const baseBox = this.#root
			? this.#getBox(this.#root.getBoundingClientRect())
			: {
					left: 0,
					top: 0,
					right: window.innerWidth,
					bottom: window.innerHeight
			  };

		const rootWidth = baseBox.right - baseBox.left;
		const rootHeight = baseBox.bottom - baseBox.top;

		const [marginTop, marginRight, marginBottom, marginLeft] = this.#rootMargin;

		return {
			left: baseBox.left - (marginLeft.unit === '%' ? (marginLeft.value / 100) * rootWidth : marginLeft.value),
			top: baseBox.top - (marginTop.unit === '%' ? (marginTop.value / 100) * rootHeight : marginTop.value),
			right: baseBox.right + (marginRight.unit === '%' ? (marginRight.value / 100) * rootWidth : marginRight.value),
			bottom: baseBox.bottom + (marginBottom.unit === '%' ? (marginBottom.value / 100) * rootHeight : marginBottom.value)
		};
	}

	/**
	 * Converts a rect to a box.
	 *
	 * @param rect Rect.
	 * @returns Box.
	 */
	private #getBox(
		rect: {
			x?: number;
			y?: number;
			width?: number;
			height?: number;
			left?: number;
			top?: number;
			right?: number;
			bottom?: number;
		}
	): IIntersectionObserverBox {
		const left = Number(rect.left ?? rect.x ?? 0);
		const top = Number(rect.top ?? rect.y ?? 0);
		const width = Number(rect.width ?? 0);
		const height = Number(rect.height ?? 0);

		return {
			left,
			top,
			right: Number(rect.right ?? left + width),
			bottom: Number(rect.bottom ?? top + height)
		};
	}

	/**
	 * Parses the root margin option.
	 *
	 * @param rootMargin Root margin.
	 * @returns Parsed root margin values in the order top, right, bottom, left.
	 */
	private #parseRootMargin(
		rootMargin: string
	): IIntersectionObserverRootMarginValue[] {
		const values = rootMargin.trim().split(/\s+/).filter((value) => value.length > 0);

		if (values.length < 1 || values.length > 4) {
			this.#throwInvalidRootMargin(rootMargin);
		}

		const parsed = values.map((value) => {
			const match = ROOT_MARGIN_VALUE_REGEXP.exec(value);

			if (!match) {
				this.#throwInvalidRootMargin(rootMargin);
			}

			return {
				value: parseFloat(match[1]),
				unit: match[2].toLowerCase() === '%' ? ('%' as const) : ('px' as const)
			};
		});

		// CSS shorthand expansion:
		// 1 value:  top right bottom left
		// 2 values: top right bottom(=top) left(=right)
		// 3 values: top right bottom left(=right)
		// 4 values: top right bottom left
		return [
			parsed[0],
			parsed[1] || parsed[0],
			parsed[2] || parsed[1] || parsed[0],
			parsed[3] || parsed[1] || parsed[0]
		];
	}

	/**
	 * Parses the threshold option.
	 *
	 * @param threshold Threshold.
	 * @returns Normalized thresholds (sorted and unique).
	 */
	private #parseThresholds(threshold: number | number[] | undefined): number[] {
		const window = this[PropertySymbol.window];
		let values: number[];

		if (threshold === undefined) {
			values = [0];
		} else if (typeof threshold === 'number') {
			values = [threshold];
		} else if (Array.isArray(threshold)) {
			values = threshold.slice();
		} else {
			throw new window.TypeError(
				`Failed to construct 'IntersectionObserver' on 'Window': The threshold provided is not a finite number.`
			);
		}

		for (const value of values) {
			if (typeof value !== 'number' || !Number.isFinite(value)) {
				throw new window.TypeError(
					`Failed to construct 'IntersectionObserver' on 'Window': The threshold provided is not a finite number.`
				);
			}
			if (value < 0 || value > 1) {
				throw new window.TypeError(
					`Failed to construct 'IntersectionObserver' on 'Window': The threshold provided must be between 0 and 1.`
				);
			}
		}

		return [...new Set(values)].sort((a, b) => a - b);
	}

	/**
	 * Throws an error for an invalid root margin.
	 *
	 * @param rootMargin Root margin.
	 */
	private #throwInvalidRootMargin(rootMargin: string): never {
		throw new this[PropertySymbol.window].SyntaxError(
			`Failed to construct 'IntersectionObserver' on 'Window': The provided root margin '${rootMargin}' is not a valid margin value.`
		);
	}
}
