/**
 * Unobserves an element.
 *
 * @param target Target.
 */
public unobserve(target: Element): void {
	if (!target) {
		return;
	}

	const state = this.#targets.get(target);

	if (!state) {
		return;
	}

	target.removeEventListener('resize', state.resizeListener);
	this.#targets.delete(target);
}

/**
 * Returns an array of IntersectionObserverEntry objects for all observed targets.
 *
 * @returns Records.
 */
public takeRecords(): IntersectionObserverEntry[] {
	const records: IntersectionObserverEntry[] = [];

	for (const state of this.#targets.values()) {
		if (state.entry) {
			records.push(state.entry);
			state.entry = null;
		}
	}

	return records;
}

/**
 * Updates the intersections for all observed targets.
 */
#updateIntersections(): void {
	if (this.#targets.size === 0) {
		return;
	}

	for (const state of this.#targets.values()) {
		const calculation = this.#calculateIntersection(state.target);

		if (this.#shouldQueueEntry(state, calculation.intersectionRatio)) {
			state.entry = this.#createEntry(state.target, calculation);
			state.intersectionRatio = calculation.intersectionRatio;
			this.#scheduleDelivery();
		}
	}
}

/**
 * Schedules delivery of the pending entries.
 */
#scheduleDelivery(): void {
	if (this.#deliveryScheduled) {
		return;
	}

	this.#deliveryScheduled = true;

	this[PropertySymbol.window].queueMicrotask(() => {
		this.#deliveryScheduled = false;

		const entries: IntersectionObserverEntry[] = [];

		for (const state of this.#targets.values()) {
			if (state.entry) {
				entries.push(state.entry);
				state.entry = null;
			}
		}

		if (entries.length > 0) {
			this.#callback(entries, this);
		}
	});
}

/**
 * Registers global listeners for window and root changes.
 */
#registerGlobalListeners(): void {
	if (this.#globalListenersRegistered) {
		return;
	}

	const window = this[PropertySymbol.window];

	window.addEventListener('resize', this.#windowListener);
	window.addEventListener('scroll', this.#windowListener);

	if (this.#root) {
		this.#root.addEventListener('resize', this.#windowListener);
		this.#root.addEventListener('scroll', this.#windowListener);
	}

	this.#globalListenersRegistered = true;
}

/**
 * Unregisters global listeners for window and root changes.
 */
#unregisterGlobalListeners(): void {
	if (!this.#globalListenersRegistered) {
		return;
	}

	const window = this[PropertySymbol.window];

	window.removeEventListener('resize', this.#windowListener);
	window.removeEventListener('scroll', this.#windowListener);

	if (this.#root) {
		this.#root.removeEventListener('resize', this.#windowListener);
		this.#root.removeEventListener('scroll', this.#windowListener);
	}

	this.#globalListenersRegistered = false;
}

/**
 * Calculates the intersection between a target and the root.
 *
 * @param target Target.
 * @returns Calculation.
 */
#calculateIntersection(
	target: Element
): IIntersectionObserverCalculation {
	const window = this[PropertySymbol.window];

	const targetBox = this.#getBox(target.getBoundingClientRect());
	const rootBox = this.#getRootBox();

	const targetWidth = targetBox.right - targetBox.left;
	const targetHeight = targetBox.bottom - targetBox.top;
	const targetArea = targetWidth * targetHeight;

	let intersectionRatio: number;
	let intersectionBox: IIntersectionObserverBox;

	if (targetArea === 0) {
		// Zero area targets have a ratio of 1 if they are contained by the root, otherwise 0.
		const isContained =
			targetBox.left >= rootBox.left &&
			targetBox.right <= rootBox.right &&
			targetBox.top >= rootBox.top &&
			targetBox.bottom <= rootBox.bottom;

		if (isContained) {
			intersectionRatio = 1;
			intersectionBox = targetBox;
		} else {
			intersectionRatio = 0;
			intersectionBox = { left: 0, top: 0, right: 0, bottom: 0 };
		}
	} else {
		const left = Math.max(targetBox.left, rootBox.left);
		const top = Math.max(targetBox.top, rootBox.top);
		const right = Math.min(targetBox.right, rootBox.right);
		const bottom = Math.min(targetBox.bottom, rootBox.bottom);
		const width = Math.max(0, right - left);
		const height = Math.max(0, bottom - top);

		intersectionRatio = Math.min(1, Math.max(0, (width * height) / targetArea));
		intersectionBox =
			width > 0 && height > 0
				? { left, top, right: left + width, bottom: top + height }
				: { left: 0, top: 0, right: 0, bottom: 0 };
	}

	return {
		intersectionRatio,
		boundingClientRect: new window.DOMRect(
			targetBox.left,
			targetBox.top,
			targetBox.right - targetBox.left,
			targetBox.bottom - targetBox.top
		),
		intersectionRect: new window.DOMRect(
			intersectionBox.left,
			intersectionBox.top,
			intersectionBox.right - intersectionBox.left,
			intersectionBox.bottom - intersectionBox.top
		),
		rootBounds: new window.DOMRect(
			rootBox.left,
			rootBox.top,
			rootBox.right - rootBox.left,
			rootBox.bottom - rootBox.top
		)
	};
}

