+		calculation: IIntersectionObserverCalculation
+	): IntersectionObserverEntry {
+		return new this[PropertySymbol.window].IntersectionObserverEntry({
+			time: Date.now(),
+			target,
+			rootBounds: calculation.rootBounds,
+			boundingClientRect: calculation.boundingClientRect,
+			intersectionRect: calculation.intersectionRect,
+			intersectionRatio: calculation.intersectionRatio,
+			isIntersecting: calculation.intersectionRatio > 0
+		});
+	}
