+			left:
+				baseBox.left -
+				(marginLeft.unit === '%' ? (marginLeft.value / 100) * rootWidth : marginLeft.value),
+			top:
+				baseBox.top -
+				(marginTop.unit === '%' ? (marginTop.value / 100) * rootHeight : marginTop.value),
+			right:
