+	 * @param rect.top
+	 * @param rect.right
+	 * @param rect.bottom
+	 * @returns Box.
+	 */
+	#getBox(rect: {
+		x?: number;
+		y?: number;
+		width?: number;
+		height?: number;
+		left?: number;
+		top?: number;
+		right?: number;
+		bottom?: number;
+	}): IIntersectionObserverBox {
+		const left = Number(rect.left ?? rect.x ?? 0);
+		const top = Number(rect.top ?? rect.y ?? 0);
+		const width = Number(rect.width ?? 0);
+		const height = Number(rect.height ?? 0);
+
+		return {
+			left,
+			top,
+			right: Number(rect.right ?? left + width),
+			bottom: Number(rect.bottom ?? top + height)
+		};
+	}
+
+	/**
+	 * Parses the root margin option.
+	 *
+	 * @param rootMargin Root margin.
+	 * @returns Parsed root margin values in the order top, right, bottom, left.
+	 */
+	#parseRootMargin(rootMargin: string): IIntersectionObserverRootMarginValue[] {
+		const values = rootMargin
+			.trim()
+			.split(/\s+/)
+			.filter((value) => value.length > 0);
+
+		if (values.length < 1 || values.length > 4) {
+			this.#throwInvalidRootMargin(rootMargin);
+		}
+
+		const parsed = values.map((value) => {
+			const match = ROOT_MARGIN_VALUE_REGEXP.exec(value);
+
+			if (!match) {
+				this.#throwInvalidRootMargin(rootMargin);
+			}
+
+			return {
+				value: parseFloat(match[1]),
+				unit: match[2].toLowerCase() === '%' ? <const>'%' : <const>'px'
+			};
+		});
